import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { SoftwarePackageService } from '../../services/software-package.service';

@Component({
  selector: 'app-add-software-package',
  templateUrl: './add-software-package.component.html',
  styleUrls: ['./add-software-package.component.css']
})
export class AddSoftwarePackageComponent implements OnInit {
  formData = {
    title: '',
    description: '',
    price: '',
    stock: '',
    category: '',
    brand: '',
    discountPercentage: '',
    thumbnail: ''
  };
  selectedFile: File | null = null;
  imagePreview: string | null = null;
  isUploading = false;
  isSubmitting = false;
  successMessage = '';
  errorMessage = '';

  constructor(private router: Router, private softwarePackageService: SoftwarePackageService, public auth: AuthService) {}

  ngOnInit(): void {
    this.auth.restoreSession();
    if (!this.auth.isAdmin) {
      this.router.navigate(['/packages']);
    }
  }

  onFileSelected(event: any): void {
    const file: File = event.target.files[0];
    if (file) {
      this.selectedFile = file;
      const reader = new FileReader();
      reader.onload = () => {
        this.imagePreview = reader.result as string;
      };
      reader.readAsDataURL(file);
    }
  }

  removeImage(): void {
    this.selectedFile = null;
    this.imagePreview = null;
    this.formData.thumbnail = '';
  }

  async uploadImage(): Promise<string | null> {
    if (!this.selectedFile) return null;

    this.isUploading = true;
    try {
      const formData = new FormData();
      formData.append('file', this.selectedFile);

      const res: any = await this.softwarePackageService.uploadImage(formData);
      return res?.fileDownloadUri || null;
    } catch (err) {
      console.error('Image upload error:', err);
      this.errorMessage = 'Failed to upload image. Please try again.';
      return null;
    } finally {
      this.isUploading = false;
    }
  }

  async handleSubmit(): Promise<void> {
    this.isSubmitting = true;
    this.successMessage = '';
    this.errorMessage = '';

    try {
      let thumbnailUrl: string = this.formData.thumbnail;

      if (this.selectedFile) {
        const uploaded = await this.uploadImage();
        if (!uploaded) {
          this.isSubmitting = false;
          return;
        }
        thumbnailUrl = uploaded;
      }

      const payload = {
        title: this.formData.title,
        description: this.formData.description,
        price: parseFloat(this.formData.price) || 0,
        stock: parseInt(this.formData.stock, 10) || 0,
        category: this.formData.category,
        brand: this.formData.brand,
        discountPercentage: parseFloat(this.formData.discountPercentage) || 0,
        thumbnail: thumbnailUrl || '',
        images: thumbnailUrl ? [thumbnailUrl] : []
      };

      const result = await this.softwarePackageService.addPackage(payload);

      if (result) {
        this.successMessage = `Software package "${result.title}" added successfully!`;

        this.formData = {
          title: '',
          description: '',
          price: '',
          stock: '',
          category: '',
          brand: '',
          discountPercentage: '',
          thumbnail: ''
        };
        this.selectedFile = null;
        this.imagePreview = null;

        setTimeout(() => {
          this.router.navigate(['/packages']);
        }, 2000);
      } else {
        this.errorMessage = 'Failed to add software package. Please try again.';
      }
    } catch (err) {
      console.error(err);
      this.errorMessage = 'An error occurred. Please try again.';
    } finally {
      this.isSubmitting = false;
    }
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="bg-white shadow-sm">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
      <div class="flex items-center justify-between">
        <div class="flex items-center gap-2">
          <div class="w-8 h-8 bg-primary rounded flex items-center justify-center">
            <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <h1 class="text-2xl font-bold text-primary">Otuya Global Digital Solution</h1>
        </div>
        <a routerLink="/packages" class="btn-secondary">
          <svg class="w-5 h-5 inline-block mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          Back to Packages
        </a>
      </div>
    </div>
  </header>

  <main class="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
    <div class="bg-white rounded-2xl shadow-lg p-8">
      <div *ngIf="successMessage" class="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg">
        <div class="flex items-center">
          <svg class="w-5 h-5 text-green-600 mr-2" fill="currentColor" viewBox="0 0 20 20">
            <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd" />
          </svg>
          <p class="text-green-700 font-medium">{{ successMessage }}</p>
        </div>
      </div>

      <div *ngIf="errorMessage" class="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg">
        <p class="text-red-600">{{ errorMessage }}</p>
      </div>

      <form (ngSubmit)="handleSubmit()" class="space-y-6">
        <div>
          <label for="title" class="block text-sm font-medium text-gray-700 mb-2">Software Package Title <span class="text-red-500">*</span></label>
          <input [(ngModel)]="formData.title" name="title" id="title" type="text" placeholder="e.g., POS Software Package" class="input-field" required />
        </div>

        <div>
          <label for="description" class="block text-sm font-medium text-gray-700 mb-2">Description <span class="text-red-500">*</span></label>
          <textarea [(ngModel)]="formData.description" name="description" id="description" rows="4" placeholder="Describe the software package..." class="input-field resize-none" required></textarea>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-6">
          <div>
            <label for="price" class="block text-sm font-medium text-gray-700 mb-2">Price ($) <span class="text-red-500">*</span></label>
            <input [(ngModel)]="formData.price" name="price" id="price" type="number" step="0.01" min="0" placeholder="0.00" class="input-field" required />
          </div>

          <div>
            <label for="stock" class="block text-sm font-medium text-gray-700 mb-2">Available Licenses <span class="text-red-500">*</span></label>
            <input [(ngModel)]="formData.stock" name="stock" id="stock" type="number" min="0" placeholder="0" class="input-field" required />
          </div>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-6">
          <div>
            <label for="category" class="block text-sm font-medium text-gray-700 mb-2">Category</label>
            <input [(ngModel)]="formData.category" name="category" id="category" type="text" placeholder="e.g., POS, Website, ERP, Apps" class="input-field" />
          </div>

          <div>
            <label for="brand" class="block text-sm font-medium text-gray-700 mb-2">Vendor / Brand</label>
            <input [(ngModel)]="formData.brand" name="brand" id="brand" type="text" placeholder="e.g., Microsoft, SAP, Oracle" class="input-field" />
          </div>
        </div>

        <div>
          <label for="discountPercentage" class="block text-sm font-medium text-gray-700 mb-2">Discount Percentage (%)</label>
          <input [(ngModel)]="formData.discountPercentage" name="discountPercentage" id="discountPercentage" type="number" step="0.01" min="0" max="100" placeholder="0" class="input-field" />
        </div>

        <div class="bg-gray-50 p-6 rounded-lg border-2 border-dashed border-gray-300">
          <label class="block text-sm font-medium text-gray-700 mb-4">Software Package Image</label>

          <div *ngIf="imagePreview" class="flex flex-col items-center gap-4">
            <img [src]="imagePreview" alt="Preview" class="w-48 h-48 object-cover rounded-lg border border-gray-200" />
            <button type="button" (click)="removeImage()" class="text-sm text-red-600 hover:text-red-800">
              <svg class="w-4 h-4 inline-block mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
              Remove Image
            </button>
          </div>

          <div *ngIf="!imagePreview" class="flex flex-col items-center gap-4">
            <label class="block">
              <input type="file" (change)="onFileSelected($event)" accept="image/*" class="block w-full text-sm text-gray-500
                file:mr-4 file:py-2 file:px-4
                file:rounded-full file:border-0
                file:text-sm file:font-semibold
                file:bg-blue-50 file:text-blue-700
                hover:file:bg-blue-100" />
            </label>
            <p class="text-xs text-gray-500">Upload a software image (JPG, PNG, up to 10MB)</p>
          </div>

          <div *ngIf="isUploading" class="text-center py-2">
            <div class="inline-block animate-spin rounded-full h-4 w-4 border-b-2 border-primary"></div>
            <span class="ml-2 text-sm text-gray-600">Uploading image...</span>
          </div>
        </div>

        <div class="flex gap-3 pt-4">
          <button type="submit" [disabled]="isSubmitting" class="btn-primary flex-1">
            <span *ngIf="isSubmitting" class="flex items-center justify-center">
              <svg class="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Adding Package...
            </span>
            <span *ngIf="!isSubmitting">
              <svg class="w-5 h-5 inline-block mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4" />
              </svg>
              Add Software Package
            </span>
          </button>
        </div>
      </form>
    </div>
  </main>
</div>
